head.script:
// https://inswave01.atlassian.net/browse/WAEA-1152



// 테스트 설명, 유효성 값 설정
//  ★ _9 : 병합 Column 옵션(ignoreSpan) 을 Body 가 MultiLine(2 Line) 인 구조에서 검증한다.
//         _8 은 단일 Line Body + colSpan 구조이며, description / validation 은 _8 과 동일하다.
scwin.tData = {
    "description" : "[gridView > M > readCSV]<br/>CSV 형식의 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "ignoreSpan(선택) 파라미터로 병합된 Column 의 데이터 처리 방식을 설정합니다.",
        "ignoreSpan(선택) 파라미터를 '0' 으로 설정 시 병합된 Column 을 하나의 Column 으로 처리합니다.",
        "ignoreSpan(선택) 파라미터를 '1' 로 설정 시 병합된 Column 을 별도의 Column 으로 각각 처리합니다.",
        "ignoreSpan(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Body 가 MultiLine(2 Line) 이면서 병합(colSpan) Column 을 가진 GridView 를 동적 생성한다.
//  · Line1 : col1 / col2 / col3 (3 Cell)
//  · Line2 : col4 (colSpan=2) / col5 (2 Cell) → col4 가 병합 Column
//  · 화면 물리 Column 수는 3, 레코드당 Body Column 수는 5
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Body 가 MultiLine(2 Line) 구조 : Line1 은 col1 / col2 / col3, Line2 는 col4 (colSpan=2) / col5 이며 col4 가 병합 Column\n- 화면 물리 Column 수는 3, 레코드당 Body Column 수는 5, Header 도 2행이므로 CSV 의 Header 도 2줄로 준비한다\n- 파일 선택 창은 화면 내 레이어(wframe) 로 고정한다\n- 테스트용 CSV 2종 (TSQA/src/sample/gridView/data/upload/ts_gridView_M_readCSV_9/) — ignoreSpan 값에 맞는 파일을 올려야 한다\n- ignoreSpan 미설정 또는 0 : ts_gridView_M_readCSV_9_upload.csv (병합 Column 을 1칸으로 센 논리 5 Column, 레코드당 1줄)\n- ignoreSpan 1 : ts_gridView_M_readCSV_9_upload_split.csv (병합 Column 을 2칸으로 센 물리 3 Column, 레코드당 2줄이며 병합 자리 두 칸에 서로 다른 값)\n[절차]\n1. Target 재생성 버튼으로 그리드를 초기 2행 상태로 되돌린다\n2. par 옵션(ignoreSpan) 값을 선택한다\n3. readCSV 버튼을 클릭한다\n4. 열린 레이어에서 위 전제에 맞는 CSV 파일을 선택하고 파일 업로드 버튼을 클릭한다\n5. 업로드결과확인 버튼을 클릭한다\n6. 다른 옵션값을 확인하려면 1번부터 반복한다\n[확인]\n- 3번 직후 결과창에 레이어가 산출한 업로드 Column 수(columnNum) 가 출력된다 (미설정 / 0 은 논리 Column 수, 1 은 화면 물리 Column 수)\n- 5번 출력의 Row 0 Body Line 수와 병합 Column(col4) colSpan 으로 MultiLine + 병합 구조가 유지되는지 확인한다\n- 5번 출력에서 병합 자리 두 칸 중 어느 값이 col4 에 반영되는지, 레코드 수가 어떻게 달라지는지 확인한다\n[왕복 참고]\n- saveCSV 버튼(구분자는 readCSV 기본값에 맞춰 쉼표 고정)으로 저장하면 화면 물리 행 기준(3 Column, 레코드당 2줄) CSV 가 내려받아진다\n- 그 파일은 ignoreSpan 1 로 올려야 원래 MultiLine 구조로 되읽히며, 미설정 / 0 으로 올리면 물리 줄마다 별도 레코드가 되어 행 수가 2배가 된다"', '', 'label1');

    // DataList 생성 (col1~col5 / 초기 2행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strDl += '<w2:column id="col5" name="name5" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '<w2:row><col1>init1_1</col1><col2>init1_2</col2><col3>init1_3</col3><col4>init1_4</col4><col5>init1_5</col5></w2:row>';
    strDl += '<w2:row><col1>init2_1</col1><col2>init2_2</col2><col3>init2_3</col3><col4>init2_4</col4><col5>init2_5</col5></w2:row>';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // target 생성 : header / gBody 각각 <w2:row> 2개 → 레코드당 2 Line
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="readCSV ignoreSpan 테스트 그리드 (Body MultiLine + 병합)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol1" value="name1"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol2" value="name2"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol3" value="name3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol4" value="name4-a"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol5" value="name4-b"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol6" value="name5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="360" style="" colSpan="2" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="col5" dataList="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

}



// par 옵션값으로 readCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · wframe 은 검증 대상이 아니며, 파일 선택 창을 화면 내 레이어로 고정하기 위해 항상 지정한다.
scwin.buildOptions = function () {
    let options = { wframe : true };

    let v = par_ignoreSpan.getValue();
    if (v !== "") options.ignoreSpan = v;

    return options;
}



// readCSV 실행
//  · ignoreSpan 자체는 레이어의 선택 필드에 렌더되지 않지만, 그 값으로 산출된 업로드 Column 수(columnNum)
//    가 레이어의 hidden 필드에 실려 있으므로 그 값을 읽어 출력한다.
scwin.btn_readCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.readCSV(scwin.buildOptions());

    setTimeout(scwin.printUploadState, 1200);
}



// 열린 업로드 레이어에 렌더된 업로드 Column 수(columnNum) 를 출력한다.
scwin.printUploadState = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objInput = document.querySelector("input[name='columnNum']");
    if (objInput === null) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        bottom.setReturnValue("CSV 파일 선택 레이어가 열려있지 않습니다.");
        return;
    }

    bottom.setReturnValue("업로드 레이어 렌더값 - 업로드 Column 수(columnNum) : [" + objInput.value + "]");
}



// CSV 저장 (왕복 참고용)
//  · saveCSV 기본 구분자는 세미콜론이고 readCSV 기본 구분자는 쉼표이므로, 왕복 시 구분자 변수를 없애기 위해
//    저장 구분자를 쉼표로 고정한다.
scwin.btn_saveCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.saveCSV({ delim : "," });

    bottom.setReturnValue("saveCSV 실행 - 구분자 쉼표 고정 (파일명 기본값 csvfile.csv)");
}



// 업로드 결과 확인 : 그리드에 실제 렌더된 MultiLine / 병합 구조와 반영된 데이터를 함께 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    // 그리드에 실제 렌더된 MultiLine / 병합 구조 확인
    //  · Row 0 의 Cell 이 몇 개의 tr 에 나뉘어 렌더되는지로 MultiLine 구성을, col4 의 colSpan 으로 병합을 확인한다
    let arrRow0Td = document.querySelectorAll("td[id*='" + target1.id + "_cell_0_']");
    let objLineSet = {};
    for (let i = 0; i < arrRow0Td.length; i++) {
        objLineSet[arrRow0Td[i].parentNode.rowIndex] = true;
    }
    let objTdCol4 = document.querySelector("td[id*='" + target1.id + "_cell_0_3']");
    let nSpan = (objTdCol4 === null) ? 0 : (objTdCol4.colSpan || 1);
    bottom.setReturnValue("렌더 구조 - Row 0 의 Body Line 수 : [" + Object.keys(objLineSet).length + "] / 병합 Column(col4) colSpan : [" + nSpan + "]");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt + " / 바인딩 DataList Row 수 : " + dlt_bind.getRowCount());
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] " + target1.getCellData(i, "col1") + " | " + target1.getCellData(i, "col2") + " | " + target1.getCellData(i, "col3") + " | " + target1.getCellData(i, "col4") + " | " + target1.getCellData(i, "col5"));
    }
}
